DELETE FROM public.quizzes WHERE title = 'Droit du travail - Session Ultime'; INSERT INTO public.quizzes (title, category, difficulty, questions) VALUES ('Droit du travail - Session Ultime', 'Droit du travail', 2, '[{"id": 1, "question": "Question 1: Selon l''Article L1237-11, comment qualifiez-vous la situation de Rupture conventionnelle ?", "options": ["R\u00e9ponse correcte selon Article L1237-11 pour le cas 1", "Interpr\u00e9tation erron\u00e9e (1)", "Application non conforme (1)", "R\u00e8gle sectorielle diff\u00e9rente (1)"], "correct_index": 0, "casus": "Sc\u00e9nario 1: Un employeur propose une rupture conventionnelle \u00e0 un salari\u00e9 prot\u00e9g\u00e9 (d\u00e9l\u00e9gu\u00e9 syndical) sans demander l''autorisation de l''inspection du travail.", "reference": "Article L1237-11", "article": "L''employeur et le salari\u00e9 peuvent convenir d''un commun accord des conditions de la rupture du contrat de travail qui les lie."}, {"id": 2, "question": "Question 2: Selon l''Article L3121-36, comment qualifiez-vous la situation de Heures suppl\u00e9mentaires ?", "options": ["R\u00e9ponse correcte selon Article L3121-36 pour le cas 2", "Interpr\u00e9tation erron\u00e9e (2)", "Application non conforme (2)", "R\u00e8gle sectorielle diff\u00e9rente (2)"], "correct_index": 0, "casus": "Sc\u00e9nario 2: L\u00e9a a travaill\u00e9 45 heures cette semaine. Son employeur refuse de payer les heures au-del\u00e0 de 35h avec majoration, pr\u00e9textant un forfait jours non \u00e9crit dans le contrat.", "reference": "Article L3121-36", "article": "A d\u00e9faut d''accord, les heures suppl\u00e9mentaires accomplies au-del\u00e0 de la dur\u00e9e l\u00e9gale hebdomadaire donnent lieu \u00e0 une majoration de salaire de 25 % pour les huit premi\u00e8res heures..."}, {"id": 3, "question": "Question 3: Selon l''Article L1221-19, comment qualifiez-vous la situation de P\u00e9riode d''essai ?", "options": ["R\u00e9ponse correcte selon Article L1221-19 pour le cas 3", "Interpr\u00e9tation erron\u00e9e (3)", "Application non conforme (3)", "R\u00e8gle sectorielle diff\u00e9rente (3)"], "correct_index": 0, "casus": "Sc\u00e9nario 3: Marc est embauch\u00e9 comme cadre. Son contrat pr\u00e9voit une p\u00e9riode d''essai de 4 mois renouvelable une fois. Apr\u00e8s 3 mois, l''employeur veut la rompre sans motif.", "reference": "Article L1221-19", "article": "Le contrat de travail \u00e0 dur\u00e9e ind\u00e9termin\u00e9e peut comporter une p\u00e9riode d''essai dont la dur\u00e9e maximale est de : deux mois pour les ouvriers et employ\u00e9s ; trois mois pour les agents de ma\u00eetrise..."}, {"id": 4, "question": "Question 4: Selon l''Article L3121-36, comment qualifiez-vous la situation de Heures suppl\u00e9mentaires ?", "options": ["R\u00e9ponse correcte selon Article L3121-36 pour le cas 4", "Interpr\u00e9tation erron\u00e9e (4)", "Application non conforme (4)", "R\u00e8gle sectorielle diff\u00e9rente (4)"], "correct_index": 0, "casus": "Sc\u00e9nario 4: L\u00e9a a travaill\u00e9 45 heures cette semaine. Son employeur refuse de payer les heures au-del\u00e0 de 35h avec majoration, pr\u00e9textant un forfait jours non \u00e9crit dans le contrat.", "reference": "Article L3121-36", "article": "A d\u00e9faut d''accord, les heures suppl\u00e9mentaires accomplies au-del\u00e0 de la dur\u00e9e l\u00e9gale hebdomadaire donnent lieu \u00e0 une majoration de salaire de 25 % pour les huit premi\u00e8res heures..."}, {"id": 5, "question": "Question 5: Selon l''Article L1152-1, comment qualifiez-vous la situation de Harc\u00e8lement moral ?", "options": ["R\u00e9ponse correcte selon Article L1152-1 pour le cas 5", "Interpr\u00e9tation erron\u00e9e (5)", "Application non conforme (5)", "R\u00e8gle sectorielle diff\u00e9rente (5)"], "correct_index": 0, "casus": "Sc\u00e9nario 5: Un manager envoie syst\u00e9matiquement des emails \u00e0 minuit demandant des r\u00e9ponses imm\u00e9diates et critique publiquement un salari\u00e9 chaque matin en r\u00e9union sans motif professionnel.", "reference": "Article L1152-1", "article": "Aucun salari\u00e9 ne doit subir les agissements r\u00e9p\u00e9t\u00e9s de harc\u00e8lement moral qui ont pour objet ou pour effet une d\u00e9gradation de ses conditions de travail..."}, {"id": 6, "question": "Question 6: Selon l''Article L3121-36, comment qualifiez-vous la situation de Heures suppl\u00e9mentaires ?", "options": ["R\u00e9ponse correcte selon Article L3121-36 pour le cas 6", "Interpr\u00e9tation erron\u00e9e (6)", "Application non conforme (6)", "R\u00e8gle sectorielle diff\u00e9rente (6)"], "correct_index": 0, "casus": "Sc\u00e9nario 6: L\u00e9a a travaill\u00e9 45 heures cette semaine. Son employeur refuse de payer les heures au-del\u00e0 de 35h avec majoration, pr\u00e9textant un forfait jours non \u00e9crit dans le contrat.", "reference": "Article L3121-36", "article": "A d\u00e9faut d''accord, les heures suppl\u00e9mentaires accomplies au-del\u00e0 de la dur\u00e9e l\u00e9gale hebdomadaire donnent lieu \u00e0 une majoration de salaire de 25 % pour les huit premi\u00e8res heures..."}, {"id": 7, "question": "Question 7: Selon l''Article L1221-19, comment qualifiez-vous la situation de P\u00e9riode d''essai ?", "options": ["R\u00e9ponse correcte selon Article L1221-19 pour le cas 7", "Interpr\u00e9tation erron\u00e9e (7)", "Application non conforme (7)", "R\u00e8gle sectorielle diff\u00e9rente (7)"], "correct_index": 0, "casus": "Sc\u00e9nario 7: Marc est embauch\u00e9 comme cadre. Son contrat pr\u00e9voit une p\u00e9riode d''essai de 4 mois renouvelable une fois. Apr\u00e8s 3 mois, l''employeur veut la rompre sans motif.", "reference": "Article L1221-19", "article": "Le contrat de travail \u00e0 dur\u00e9e ind\u00e9termin\u00e9e peut comporter une p\u00e9riode d''essai dont la dur\u00e9e maximale est de : deux mois pour les ouvriers et employ\u00e9s ; trois mois pour les agents de ma\u00eetrise..."}, {"id": 8, "question": "Question 8: Selon l''Article L1237-11, comment qualifiez-vous